messages.content:
        return (int(match.group(1)), match.group(2))
    return None

def _is_vision_qkv_component(self, name: str) -> Optional[Tuple[int, str, str]]:
    """
    Check if a mapped model parameter name is a vision QKV component.

    Returns:
        Tuple of (layer_idx, component, suffix) if it's a vision QKV
        component, None otherwise. ``suffix`` is "weight" or "bias".
    """
    import re

    pattern = (
        r"vision_model\.encoder\.layers\.(\d+)"
        r"\.attn\.(q_proj|k_proj|v_proj)\.(weight|bias)$"
    )
    match = re.match(pattern, name)
    if match:
        return (int(match.group(1)), match.group(2), match.group(3))
    return None

def _is_expert_weight(self, name: str) -> Optional[str]:
    """
    Check if tensor name is an expert weight or scale that needs EP/TP sharding.

    Returns:
        "w13" or "w2" if it's an expert weight/scale, None otherwise.
    """
    if name.endswith("feed_forward.experts.w13_weight"):
        return "w13"
    if name.endswith("feed_forward.experts.w2_weight"):
        return "w2"
    if name.endswith("feed_forward.experts.w13_weight_scale"):
        return "w13"
    if name.endswith("feed_forward.experts.w2_weight_scale"):
        return "w2"
    if name.endswith("feed_forward.experts.w13_weight_scale_2"):
        return "w13"
    if name.endswith("feed_forward.experts.w2_weight_scale_2"):
        return "w2"
    if name.endswith("feed_forward.experts.w13_input_scale"):
        return "w13"
    if name.endswith("feed_forward.experts.w2_input_scale"):
        return "w2"
    return None

def _shard_expert_weight(
    self,
    weight: torch.Tensor,
    weight_type: str,
    global_num_experts: int,
    expert_placement_strategy: str = "linear",
) -> torch.Tensor:
    """
    Apply EP slicing and TP sharding to expert weights or scales.

    EP slicing is only applied when EP is enabled.
    TP sharding is always applied when TP > 1.

    Args:
        weight: Full expert weight tensor [global_experts, dim1, dim2]
                or scale tensor [global_experts, channels]
        weight_type: "w13" or "w2"
        global_num_experts: Total number of experts in the model
        expert_placement_strategy: How experts are distributed

    Returns:
        Weight tensor for this rank (EP sliced if enabled, TP sharded if TP > 1).
    """
    is_scale = weight.dim() <= 2

    # Step 1: EP slicing - select local experts only (skip if EP disabled)
    if self.ep_enabled and self.ep_size > 1:
        local_num_experts, expert_map, _ = determine_expert_map(
            ep_size=self.ep_size,
            ep_rank=self.ep_rank,
            global_num_experts=global_num_experts,
            expert_placement_strategy=expert_placement_strategy,
        )

        if expert_map is not None:
            expert_map_cpu = (
                expert_map.cpu() if expert_map.device.type != "cpu" else expert_map
            )
            local_indices = (expert_map_cpu >= 0).nonzero(as_tuple=True)[0]
            weight = weight[local_indices]
        else:
            local_num_experts = global_num_experts // self.ep_size
            expert_start = self.ep_rank * local_num_experts
            expert_end = expert_start + local_num_experts
            weight = weight[expert_start:expert_end]

    # Step 2: TP sharding - shard intermediate dimension
    # - Pure EP (no elastic): skip TP shard (each rank owns full experts)
    # - Pure TP (no EP): standard TP shard
    if self.tp_size > 1 and not self.ep_enabled:
        tp_size = self.tp_size
        tp_rank = self.tp_rank
        do_tp_shard = True
    else:
        do_tp_shard = False

    if do_tp_shard:
        if is_scale:
            if weight_type == "w13":
                # w13 scale: [E, 2*intermediate] → shard gate and up halves
                intermediate = weight.shape[1] // 2
                shard_size = intermediate // tp_size
                start = tp_rank * shard_size
                gate = weight[:, :intermediate]
                up = weight[:, intermediate:]
                gate_shard = gate[:, start : start + shard_size]
                up_shard = up[:, start : start + shard_size]
                weight = torch.cat([gate_shard, up_shard], dim=1)
            else:  # w2
                # w2 scale: [E, hidden] → shard is not needed (scales
                # align with the output dim which is not sharded for w2)
                pass
        else:
            # 3D weight tensor [experts, dim1, dim2]
            if weight_type == "w13":
                # w13: [experts, 2*intermediate, hidden] where layout is [gate, up]
                intermediate = weight.shape[1] // 2
                shard_size = intermediate // tp_size
                start = tp_rank * shard_size

                gate = weight[:, :intermediate, :]
                up = weight[:, intermediate:, :]

                gate_shard = gate[:, start : start + shard_size, :]
                up_shard = up[:, start : start + shard_size, :]

                weight = torch.cat([gate_shard, up_shard], dim=1)
            else:  # w2
                # w2: [experts, hidden, intermediate] -> shard dim 2
                shard_size = weight.shape[2] // tp_size
                start = tp_rank * shard_size
                weight = weight[:, :, start : start + shard_size]

    return weight.contiguous()

def _get_global_num_experts(self, hf_config) -> int:
    if hasattr(hf_config, "moe") and hasattr(hf_config.moe, "num_experts"):
        return hf_config.moe.num_experts
    if hasattr(hf_config, "num_local_experts"):
        return hf_config.num_local_experts
    logger.warning("Could not find num_experts in config, using default: 128")
    return 128

def _get_expert_placement_strategy(self, model: torch.nn.Module) -> str:
    if hasattr(model, "model") and hasattr(model.model, "parallel_config"):
        parallel_config = model.model.parallel_config
        if hasattr(parallel_config, "expert_placement_strategy"):
            return parallel_config.expert_placement_strategy
    return "linear"

def _get_contiguous_ep_slice_range(
    self,
    global_num_experts: int,
    expert_placement_strategy: str,
) -> Optional[Tuple[int, int]]:
    if not (self.ep_enabled and self.ep_size > 1):
        return None

    local_num_experts, expert_map, _ = determine_expert_map(
        ep_size=self.ep_size,
        ep_rank=self.ep_rank,
        global_num_experts=global_num_experts,
        expert_placement_strategy=expert_placement_strategy,
    )
    if expert_map is not None:
        local_indices = (expert_map >= 0).nonzero(as_tuple=True)[0]
        n_local = len(local_indices)
        if n_local > 0 and (local_indices[-1] - local_indices[0] + 1) == n_local:
            return (local_indices[0].item(), local_indices[-1].item() + 1)
        return None

    ep_start = self.ep_rank * local_num_experts
    return (ep_start, ep_start + local_num_experts)

def _get_tp_shard_strategy(self, name: str) -> Optional[Tuple[int, str]]:
    """
    Determine TP sharding strategy for non-expert weights.

    Returns:
        Tuple of (dim, strategy) where strategy is "column" or "row",
        or None if the weight should be replicated.
    """
    # Audio perception encoder weights are fully replicated across ranks
    # Must check before general patterns since they match suffixes like o_proj.weight
    if "audio_encoder" in name:
        return None

    # Vision encoder weights are fully replicated when using vision DP mode
    # (each TP rank has full vision weights and processes different images)
    if self._use_vision_dp and "vision_model." in name:
        return None

    # These role names overlap as suffixes: ``unpooler.weight`` also ends
    # with ``pooler.weight``. Resolve them before the general suffix table
    # so the two replication flags remain independent.
    if name.endswith("unpooler.weight"):
        return None if USE_REPLICATED_UNPOOLER else (0, "column")
    if name.endswith("pooler.weight"):
        return None if USE_REPLICATED_POOLER else (0, "column")

    # Column parallel (shard dim 0)
    column_parallel_patterns = [
        "qkv_proj.weight",
        "q_proj.weight",
        "k_proj.weight",
        "v_proj.weight",
        "o_gate_proj.weight",
        "embed_tokens.weight",
        "lm_head.weight",
        "gate_up_proj.weight",
        "gate_proj.weight",
        "up_proj.weight",
        # Audio generation modality (VocabParallelEmbedding)
        "tok_embeddings.weight",
        # Vision encoder
        "conv1_linear.weight",
        # GDN (Gated Delta Net) column parallel params
        "self_attn.A",
        "self_attn.dt_bias",
        "self_attn.q_conv1d_weight",
        "self_attn.k_conv1d_weight",
        "self_attn.v_conv1d_weight",
    ]
    for pattern in column_parallel_patterns:
        if name.endswith(pattern):
            return (0, "column")

    # Vision MLP and adapter column parallel (weight AND bias)
    if name.endswith("c_fc.weight") or name.endswith("c_fc.bias"):
        if "vision_model." in name:
            return (0, "column")

    # Row parallel (shard dim 1)
    row_parallel_patterns = [
        "o_proj.weight",
        "down_proj.weight",
    ]
    for pattern in row_parallel_patterns:
        if name.endswith(pattern):
            return (1, "row")

    if name.endswith("out_proj.weight") and "vision_model." in name:
        return (1, "row")
    if name.endswith("c_proj.weight") and "vision_model." in name:
        return (1, "row")

    if name.endswith("vision_projection.weight"):
        if self._use_rowwise_vision_projection:
            return (1, "row")
        else:
            return (0, "column")

    # Optional generative-modality latent projections are TP-sharded on the latent dim:
    # input_projection (latent->hidden) is row-parallel (shard dim 1);
    # output (hidden->latent) is column-parallel (shard dim 0).
    if "modalities." in name:
        if name.endswith("input_projection.weight"):
            return (1, "row")
        if name.endswith("output.weight"):
            return (0, "column")

    # Replicated (no sharding): norms, router, gates, biases, expert_bias,
    # vision out_proj.bias, c_proj.bias, ln_*, positional_embedding
    return None

def _apply_tp_shard(self, weight: torch.Tensor, dim: int) -> torch.Tensor:
    """Apply tensor parallel sharding along specified dimension."""
    if self.tp_size <= 1:
        return weight

    shard_size = weight.shape[dim] // self.tp_size
    start = self.tp_rank * shard_size

    if dim == 0:
        return weight[start : start + shard_size].contiguous()
    elif dim == 1:
        return weight[:, start : start + shard_size].contiguous()
    else:
        raise ValueError(f"Unsupported shard dimension: {dim}")

def _maybe_strip_attention_padding(
    self, name: str, tensor: torch.Tensor
) -> torch.Tensor:
    """
    Strip zero-padding from non-QKV attention weights (e.g., o_proj).

    QKV components (q_proj, k_proj, v_proj, o_gate_proj) are handled by
    QKVFusionHandler._strip_padding_if_needed(). This method handles the
    remaining attention weights that are not part of QKV fusion but may
    still be padded for TP alignment.

    For o_proj (row parallel), padding is on dim 1:
      checkpoint: [hidden_size, padded_heads * head_dim]
      expected:   [hidden_size, num_attention_heads * head_dim]
    """
    num_heads = self._config_num_attention_heads
    head_dim = self._config_head_dim
    if num_heads is None or head_dim is None:
        return tensor

    expected_attn_dim = num_heads * head_dim

    # o_proj: row parallel — padding is on dim 1
    if name.endswith("self_attn.o_proj.weight") and tensor.dim() == 2:
        if tensor.shape[1] > expected_attn_dim:
            padding = tensor[:, expected_attn_dim:]
            if not padding.any():
                logger.info(
                    f"Stripped zero-padding from {name}: "
                    f"checkpoint dim1={tensor.shape[1]} -> "
                    f"config dim1={expected_attn_dim} "
                    f"(removed {tensor.shape[1] - expected_attn_dim} "
                    f"padding columns)"
                )
                return tensor[:, :expected_attn_dim].contiguous()
            else:
                raise ValueError(
                    f"{name} has extra columns "
                    f"({tensor.shape[1]} > expected {expected_attn_dim}) "
                    f"with NON-ZERO values. This is not TP-alignment "
                    f"padding — the checkpoint architecture does not "
                    f"match config (num_attention_heads={num_heads}, "
                    f"head_dim={head_dim})."
                )

    # o_norm (if present): padding on dim 0
    if name.endswith("self_attn.o_norm.weight") and tensor.dim() == 1:
        if tensor.shape[0] > expected_attn_dim:
            padding = tensor[expected_attn_dim:]
            if not padding.any():
                logger.info(
                    f"Stripped zero-padding from {name}: "
                    f"checkpoint dim0={tensor.shape[0]} -> "
                    f"config dim0={expected_attn_dim} "
                    f"(removed {tensor.shape[0] - expected_attn_dim} "
                    f"padding elements)"
                )
                return tensor[:expected_attn_dim].contiguous()
            else:
                raise ValueError(
                    f"{name} has extra elements "
                    f"({tensor.shape[0]} > expected {expected_attn_dim}) "
                    f"with NON-ZERO values. This is not TP-alignment "
                    f"padding — the checkpoint architecture does not "
                    f"match config (num_attention_heads={num_heads}, "
                    f"head_dim={head_dim})."
                )

    return tensor

def _process_single_tensor(
    self,
    name: str,
    tensor: torch.Tensor,
    qkv_handler: QKVFusionHandler,
    global_num_experts: int,
    expert_placement_strategy: str,
    flatten_expert_weights: bool,
    vision_qkv_weight_handler: Optional[QKVFusionHandler] = None,
    vision_qkv_bias_handler: Optional[QKVFusionHandler] = None,
) -> Optional[Tuple[str, torch.Tensor]]:
    """
    Process a single tensor from checkpoint, applying necessary transformations.

    Handles vision QKV fusion, LLM QKV fusion, expert sharding, router
    transpose, and TP sharding.

    Vision tensors already arrive under model-compatible ``vision_model.*`` names.

    Args:
        name: Tensor name from checkpoint
        tensor: Raw tensor from checkpoint
        qkv_handler: Handler for LLM QKV fusion
        global_num_experts: Total number of experts in the model
        expert_placement_strategy: How experts are distributed
        flatten_expert_weights: Whether to flatten 3D expert weights to 2D
        vision_qkv_weight_handler: Handler for vision QKV weight fusion
        vision_qkv_bias_handler: Handler for vision QKV bias fusion

    Returns:
        Tuple of (name, transformed_tensor) or None if tensor is buffered
        (e.g., QKV fusion pending).
    """
    import re

    name = re.sub(
        r"^modalities\.soft_audio_perception\.(?:interaction_)?encoder\.",
        "audio_encoder.",
        name,
    )

    # Must run after the perception remap above, which this pattern would also match.
    name = re.sub(r"^modalities\..+?\.*encoder\.", "", name)

    # Case 0: Vision QKV component — buffer for fusion
    vision_qkv_info = self._is_vision_qkv_component(name)
    if vision_qkv_info is not None:
        layer_idx, component, suffix = vision_qkv_info
        if suffix == "weight" and vision_qkv_weight_handler is not None:
            return vision_qkv_weight_handler.add_weight(
                layer_idx, component, tensor
            )
        elif suffix == "bias" and vision_qkv_bias_handler is not None:
            return vision_qkv_bias_handler.add_weight(layer_idx, component, tensor)

    # Case 1: QKV component - buffer for fusion
    qkv_info = self._is_qkv_component(name)
    if qkv_info is not None:
        layer_idx, component = qkv_info
        return qkv_handler.add_weight(layer_idx, component, tensor)

    # Case 2: Expert weight - apply EP slicing + TP sharding
    expert_type = self._is_expert_weight(name)
    if expert_type is not None:
        if "input_scale" not in name:
            tensor = self._shard_expert_weight(
                tensor,
                expert_type,
                global_num_experts,
                expert_placement_strategy,
            )
        # Flatten 3D expert weights to 2D if requested
        if flatten_expert_weights and tensor.dim() == 3:
            num_experts, dim1, dim2 = tensor.shape
            tensor = tensor.view(-1, dim2)
            logger.debug(
                f"Flattened expert weight {name}: "
                f"[{num_experts}, {dim1}, {dim2}] -> {tensor.shape}"
            )
        return (name, tensor)

    # Case 3: Router weight - may need transpose
    # Checkpoint format: [hidden_dim, num_experts]
    # Model expects: [num_experts, hidden_dim]
    if "feed_forward.router.weight" in name:
        if tensor.dim() == 2 and tensor.shape[0] > tensor.shape[1]:
            tensor = tensor.t().contiguous()
            logger.debug(f"Transposed router weight {name} to shape {tensor.shape}")
        return (name, tensor)

    # Strip TP-alignment padding from attention weights (o_proj, o_norm)
    # before TP sharding. QKV components are handled in QKVFusionHandler.
    tensor = self._maybe_strip_attention_padding(name, tensor)

        )

    def forward(
        self,
        positions: torch.Tensor,
        hidden_states: torch.Tensor,
        residual: torch.Tensor | None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        # Self Attention
        if residual is None:
            residual = hidden_states
            hidden_states = self.input_layernorm(hidden_states)
        else:
            hidden_states, residual = self.input_layernorm(hidden_states, residual)
        hidden_states = self.self_attn(
            positions=positions,
            hidden_states=hidden_states,
        )

        # Fully Connected
        hidden_states, residual = self.post_attention_layernorm(hidden_states, residual)
        hidden_states = self.mlp(hidden_states)
        return hidden_states, residual


